import React, { useEffect, useState, type FC, type ReactNode } from 'react';
import {
  getAuthUser,
  hasValidAuthToken,
  migrateLegacyActiveCompanyId,
} from '@linm-soft-org/linm-web-common-components';
import { isStandalone } from '../dev/isStandalone';
import { reconcileActiveCompanyForUser } from '../utils/reconcileActiveCompany';

/** Embedded: migrate + reconcile before list/API effects (async migrate race). */
export async function runTenantReconcile(): Promise<void> {
  const user = getAuthUser();
  await migrateLegacyActiveCompanyId(user?.companyId);
  reconcileActiveCompanyForUser(getAuthUser());
}

function bindTenantReconcileOnAuthChange(sync: () => void): () => void {
  window.addEventListener('linm:auth:changed', sync);
  window.addEventListener('linm:auth:token-changed', sync);
  window.addEventListener('linm:company:changed', sync);

  return () => {
    window.removeEventListener('linm:auth:changed', sync);
    window.removeEventListener('linm:auth:token-changed', sync);
    window.removeEventListener('linm:company:changed', sync);
  };
}

/**
 * Embedded only — block routes until first tenant reconcile completes.
 * Standalone: `StandaloneEntry` seeds mock auth (Admin MFE-CORE pattern).
 */
export const TenantBootstrapGate: FC<{ children: ReactNode }> = ({ children }) => {
  const [ready, setReady] = useState(isStandalone);

  useEffect(() => {
    if (isStandalone) return;

    let cancelled = false;
    let initialReady = false;
    const markReadyOnce = () => {
      if (!cancelled && !initialReady) {
        initialReady = true;
        setReady(true);
      }
    };

    const releaseAfterReconcile = () => {
      void runTenantReconcile().finally(markReadyOnce);
    };

    if (hasValidAuthToken()) {
      releaseAfterReconcile();
    } else {
      const onAuthReady = () => {
        if (!hasValidAuthToken()) return;
        releaseAfterReconcile();
      };
      window.addEventListener('linm:auth:changed', onAuthReady);
      window.addEventListener('linm:auth:token-changed', onAuthReady);
      // Shell may inject token after MFE mount — short wait before ForbiddenPage.
      const fallback = window.setTimeout(markReadyOnce, 800);
      return () => {
        cancelled = true;
        window.clearTimeout(fallback);
        window.removeEventListener('linm:auth:changed', onAuthReady);
        window.removeEventListener('linm:auth:token-changed', onAuthReady);
      };
    }

    const unbind = bindTenantReconcileOnAuthChange(releaseAfterReconcile);

    return () => {
      cancelled = true;
      unbind();
    };
  }, []);

  if (!ready) return null;
  return <>{children}</>;
};

/** @deprecated Use TenantBootstrapGate */
export function bootstrapTenantContext(): void {
  if (isStandalone) return;
  void runTenantReconcile();
}
